const meta: Meta<typeof Button> = {
  component: Button,
  parameters: {
    chromaticProvider: {disableAnimations: true}
  },
  title: 'S2 Chromatic/Button'
};

export default meta;

let states = [
  {isQuiet: true},
  {isDisabled: true},
  {size: ['S', 'M', 'L', 'XL']},
  {staticColor: ['black', 'white']},
  {variant: ['accent', 'negative', 'primary', 'secondary']}
];

let combinations = generatePowerset(states);

let premiumStates = [{isDisabled: true}, {size: ['S', 'M', 'L', 'XL']}];

let premiumCombinations = generatePowerset(premiumStates);

let genaiStates = [{isDisabled: true}, {size: ['S', 'M', 'L', 'XL']}];

let genaiCombinations = generatePowerset(genaiStates);

let staticColorAutoStates = [
  {isQuiet: true},
  {isDisabled: true},
  {size: ['S', 'M', 'L', 'XL']},
  {staticColor: ['auto']},
  {variant: ['accent', 'negative', 'primary', 'secondary']}
];

let staticColorAutoCombinations = generatePowerset(staticColorAutoStates).filter(
  c => c.staticColor != null
);

const Template = (args: ButtonProps & {combos?: any[]}): ReactNode => {
  let {children, combos = combinations, variant, ...otherArgs} = args;
  return (
    <div
      className={style({
        display: 'grid',
        gridTemplateColumns: 'repeat(4, minmax(0, 250px))',
        gridAutoFlow: 'row',
        alignItems: 'center',
        justifyItems: 'start',
        gap: 24,
        width: '100vw'
      })}>
      {combos.map(c => {
        let fullComboName = Object.keys(c)
          .map(k => `${k}: ${c[k]}`)
          .join(' ');
        let key = Object.keys(c)
          .map(k => shortName(k, c[k]))
          .join(' ');
        if (!key) {
          key = 'default';
        }

        let finalVariant = c.variant ?? variant;
        let buttonProps = {...otherArgs, ...c, ...(finalVariant && {variant: finalVariant})};
        let button = (
          <Button data-testid={fullComboName} key={key} {...buttonProps}>
            {children ? children : key}
          </Button>
        );
        if (c.staticColor != null) {
          return (
            <StaticColorProvider key={`static-${key}`} staticColor={c.staticColor} hideColorPicker>
              {button}
            </StaticColorProvider>
          );
        }

        return button;
      })}
    </div>
  );
};

