  value: string;
  src?: string;
  event?: Event["name"];
  proxyId?: string;
}

export async function copyToClipboardWithMeta(value: string, event?: Event) {
  navigator.clipboard.writeText(value);
  if (event) {
    trackEvent(event);
  }
}

export function CopyButton({
  value,
  className,
  variant = "ghost",
  event,
  proxyId,
  ...props
}: CopyButtonProps) {
  const [hasCopied, setHasCopied] = useCopyReset();

  return (
    <Button
      size="icon"
      variant={variant}
      className={cn("relative z-10 h-6 w-6 bg-zinc-500 text-zinc-50 [&_svg]:size-3", className)}
      onClick={() => {
        if (proxyId) {
          document.getElementById(proxyId)?.click();
          setHasCopied(true);
          return;
        }

        copyToClipboardWithMeta(
          value,
          event
            ? {
                name: event,
                properties: {
                  code: value,
                  proxyId: proxyId ?? "",
                },
              }
            : undefined,
        );
        setHasCopied(true);
      }}
      {...props}
    >
      <span className="sr-only">Copy</span>
      {hasCopied ? <CheckIcon /> : <ClipboardIcon />}
    </Button>
  );
}

